import * as THREE from './vendor/three.module.js';
import { GLTFLoader } from './vendor/GLTFLoader.js';
import { OrbitControls } from './vendor/OrbitControls.js';
const $=s=>document.querySelector(s);
let session, current, mode='3d', pollTimer, waitingTicker, render, world, camera, controls, model, frameId, loadSequence=0;
const readySession=fetch('/api/session').then(async r=>{if(!r.ok)throw Error('服务端未连接');session=await r.json();budget(session);return session;});
readySession.catch(()=>{});
function budget(data){$('#budget-label').textContent=`本轮 ${data.attempts} / ${data.limit} 次`;}
async function request(path,options={}){const s=await readySession;const r=await fetch(path,{signal:AbortSignal.timeout(20000),...options,headers:{'Content-Type':'application/json','X-Pensieve-Token':s.token,...options.headers}});const data=await r.json();if(!r.ok)throw Error(data.error||'请求暂时无法完成');return data;}
export async function loadSavedMemories(){await readySession;const data=await request('/api/memories');budget(data);const saved=[];for(const m of data.items){const img=new Image();img.src=m.photo_url;try{await img.decode();saved.push({...m,img,url:m.photo_url})}catch{}}return saved;}
function setMessage(title,text,working=false){clearInterval(waitingTicker);$('#model-title').textContent=title;$('#model-message').textContent=text;$('#model-state').classList.toggle('is-working',working);$('#model-state').hidden=false;$('#model-controls').hidden=true;}
function disposeModel(object){if(!object)return;object.traverse(n=>{n.geometry?.dispose();const mats=Array.isArray(n.material)?n.material:[n.material];for(const m of mats){if(!m)continue;for(const v of Object.values(m))if(v?.isTexture)v.dispose();m.dispose();}});}
function setupViewer(){if(render)return;render=new THREE.WebGLRenderer({antialias:true,alpha:true});render.setPixelRatio(Math.min(devicePixelRatio,2));render.outputColorSpace=THREE.SRGBColorSpace;render.toneMapping=THREE.ACESFilmicToneMapping;render.toneMappingExposure=1.3;$('#model-stage').append(render.domElement);world=new THREE.Scene();camera=new THREE.PerspectiveCamera(40,1,.01,100);camera.position.set(3,2,4);controls=new OrbitControls(camera,render.domElement);controls.enableDamping=true;controls.enablePan=false;controls.minDistance=1;controls.maxDistance=12;world.add(new THREE.HemisphereLight(0xe5f7ff,0x79786b,3));for(const [x,y,z,color,power] of [[3,5,4,0xfff0d6,4],[-4,2,1,0x9adbe4,2],[-1,4,-4,0xd4e9ff,3]]){const light=new THREE.DirectionalLight(color,power);light.position.set(x,y,z);world.add(light);}const ring=new THREE.Mesh(new THREE.TorusGeometry(1.8,.008,6,100),new THREE.MeshBasicMaterial({color:0x689b99,transparent:true,opacity:.4}));ring.rotation.x=Math.PI/2;ring.position.y=-1.35;world.add(ring);new ResizeObserver(resizeViewer).observe($('#model-stage'));}
function resizeViewer(){if(!render)return;const {width,height}=$('#model-stage').getBoundingClientRect();if(!width||!height)return;render.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();}
function draw(){if($('#memory-view').hidden||mode!=='3d'){frameId=null;return;}controls.update();render.render(world,camera);frameId=requestAnimationFrame(draw);}
function startDrawing(){resizeViewer();if(!frameId)frameId=requestAnimationFrame(draw);}
export function stopModelView(){clearTimeout(pollTimer);clearInterval(waitingTicker);if(frameId)cancelAnimationFrame(frameId);frameId=null;}
async function loadModel(m){setupViewer();const sequence=++loadSequence;setMessage('记忆正在显形','正在加载 AHOLO 生成的 3D 模型…',true);try{const gltf=await new GLTFLoader().loadAsync(m.model_url);if(sequence!==loadSequence||current!==m){disposeModel(gltf.scene);return;}if(model){world.remove(model);disposeModel(model);}model=gltf.scene;const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),scale=2.5/Math.max(size.x,size.y,size.z,.001);model.scale.multiplyScalar(scale);model.position.sub(center.multiplyScalar(scale));world.add(model);camera.position.set(3,1.6,4);controls.target.set(0,0,0);controls.update();$('#model-state').hidden=true;$('#model-controls').hidden=mode!=='3d';$('#model-stage').dataset.loaded='true';if(mode==='3d')startDrawing();}catch{if(sequence!==loadSequence||current!==m)return;setMessage('模型暂未打开','模型已保存在本地。可以重新打开记忆再加载，不会再次生成。');}}
function showState(m){if($('#open-world'))$('#open-world').hidden=true;$('#generate-3d').hidden=true;$('#resume-3d').hidden=true;$('#upload-note').hidden=!!m.id;$('#upload-note').textContent='生成时仅上传当前照片，模型保存在这台电脑。';if(m.mode==='world'){showWorldState(m);return;}if(m.status==='ready'&&m.model_url){loadModel(m);return;}if(['uploading','submitting','generating','caching'].includes(m.status)){setMessage('记忆正在成为立体',m.message||'AHOLO 正在生成，请稍候…',true);showWaitingTime(m);schedulePoll(m);return;}if(['failed','uncertain','paused'].includes(m.status)){setMessage(m.status==='paused'?'记忆暂时停留在途中':'这段记忆尚未显形',m.message);$('#resume-3d').hidden=!(m.status==='paused'&&(m.task_id||m.world_id));return;}setMessage('让这一刻拥有形状','将这张照片交给 AHOLO，生成可以转动的 3D 记忆。');$('#generate-3d').hidden=false;$('#generate-3d').disabled=true;readySession.then(s=>{if(current!==m)return;$('#generate-3d').disabled=!s.configured;if(!s.configured)$('#model-message').textContent='请先在服务端配置 AHOLO_KEY，原照片仍可查看。'}).catch(()=>{if(current===m)$('#model-message').textContent='AHOLO 服务暂未连接，原照片仍可查看。'});}
function setMode(next){mode=next;$('#mode-3d').setAttribute('aria-pressed',String(mode==='3d'));$('#mode-photo').setAttribute('aria-pressed',String(mode==='photo'));$('#memory-photo').hidden=mode!=='photo';$('#model-stage').hidden=mode!=='3d';$('#model-state').hidden=mode!=='3d';$('#model-controls').hidden=true;if(mode==='photo'){stopModelView();}else if(current){showState(current);}}
export function displayMemory(m){stopModelView();loadSequence++;if(model){world.remove(model);disposeModel(model);model=null;render.clear();}current=m;$('#memory-name').textContent=m.name||'我的记忆';$('#model-stage').dataset.loaded='false';setMode('3d');if(m.id&&m.status!=='ready')refreshMemory(m);}
async function refreshMemory(m){try{const data=await request('/api/memories');budget(data);const latest=data.items.find(x=>x.id===m.id);if(latest)Object.assign(m,latest);if(current===m&&mode==='3d')showState(m);}catch{/* scheduled polling will retry */}}
function showWaitingTime(m){const tick=()=>{if(current!==m||mode!=='3d')return;const seconds=Math.max(0,Math.floor(Date.now()/1000-(m.created_at||Date.now()/1000)));const elapsed=`${Math.floor(seconds/60)} 分 ${String(seconds%60).padStart(2,'0')} 秒`;$('#model-message').textContent=`${m.message||'AHOLO 正在生成 3D 记忆'}。已等待 ${elapsed}。`;$('#upload-note').hidden=false;$('#upload-note').textContent='每 12 秒自动查询 · 可以关闭窗口，稍后回来 · 无需重复生成';};tick();waitingTicker=setInterval(tick,1000);}
function schedulePoll(m){clearTimeout(pollTimer);pollTimer=setTimeout(async()=>{if(current!==m||$('#memory-view').hidden||mode!=='3d')return;try{const data=await request('/api/memories');budget(data);const latest=data.items.find(x=>x.id===m.id);if(latest)Object.assign(m,latest);if(current===m&&mode==='3d')showState(m);}catch{if(current===m){setMessage('仍在等待记忆','连接暂时中断，正在继续查询已有任务…',true);schedulePoll(m);}}},12000);}
$('#mode-3d').onclick=()=>setMode('3d');$('#mode-photo').onclick=()=>setMode('photo');
$('#generate-3d').onclick=async()=>{const m=current;if(!m||m.id||m.submitting)return;m.submitting=true;$('#generate-3d').disabled=true;setMessage('正在交出这一缕记忆','正在上传当前照片，其他照片不会上传…',true);try{const canvas=document.createElement('canvas'),s=Math.min(1,2048/Math.max(m.img.width,m.img.height));canvas.width=Math.max(1,Math.round(m.img.width*s));canvas.height=Math.max(1,Math.round(m.img.height*s));canvas.getContext('2d').drawImage(m.img,0,0,canvas.width,canvas.height);const image=canvas.toDataURL('image/jpeg',.9).split(',')[1];const result=await request('/api/memories',{method:'POST',body:JSON.stringify({image,name:m.name})});Object.assign(m,result);if(current===m&&mode==='3d')showState(m);request('/api/memories').then(budget).catch(()=>{});}catch(e){if(current===m){setMessage('暂时无法开始生成',e.message);$('#generate-3d').disabled=false;}}finally{m.submitting=false;}};
$('#resume-3d').onclick=async()=>{const m=current;$('#resume-3d').disabled=true;try{await request(`/api/resume/${m.id}`,{method:'POST',body:'{}'});m.status='generating';m.message='正在查询已有任务，不会重新生成';if(current===m)showState(m);}catch(e){if(current===m)setMessage('查询暂未恢复',e.message);}finally{$('#resume-3d').disabled=false;}};

function showWorldState(m){if(['failed','paused','uncertain'].includes(m.status)){setMessage('空间任务暂未完成',m.message);$('#resume-3d').hidden=!(m.status==='paused'&&m.world_id);return;}if(m.status==='ready'){setMessage('空间记忆已生成','点击下方入口，在独立空间窗口环顾并对比原照片。');let link=$('#open-world');if(!link){link=document.createElement('a');link.id='open-world';link.className='world-link';$('#model-state').append(link);}link.href=`/world/?id=${m.id}`;link.textContent='进入 World 记忆空间 ↗';link.hidden=false;}else{setMessage('空间正在展开',m.message,true);showWaitingTime(m);schedulePoll(m);}}
